<script setup>
import {computed,onMounted,ref} from 'vue';import {get,pct} from '../api/client';import DataTable from '../components/DataTable.vue';import StockHistoryModal from '../components/StockHistoryModal.vue';
const modelNames={multi_factor_rank:'次日方向模型',tradeable_t1_open:'T+1可交易模型'},runs=ref([]),activeModel=ref('multi_factor_rank'),selected=ref({}),data=ref({groups:[],detail:[]}),historyStock=ref(null);const modelRuns=computed(()=>runs.value.filter(r=>r.model_code===activeModel.value));const isTradeable=computed(()=>activeModel.value==='tradeable_t1_open');async function load(){const id=selected.value[activeModel.value];data.value=id?await get(`/verifications/${id}`):{groups:[],detail:[]}}async function switchModel(code){activeModel.value=code;await load()}onMounted(async()=>{runs.value=await get('/verifications');for(const code of Object.keys(modelNames))selected.value[code]=runs.value.find(r=>r.model_code===code)?.id;await load()});
const groups=[{label:'TopN',key:'top_n'},{label:'已验证',key:'verified_count'},{label:'上涨数',key:'up_count'},{label:'上涨比例',key:'up_rate',format:pct},{label:'平均收益',key:'avg_return',format:pct},{label:'超额收益',key:'excess_return',format:pct}];const detail=computed(()=>[{label:'排名',key:'ranking'},{label:'代码',key:'stock_code',action:r=>historyStock.value=r},{label:'市场',key:'market'},{label:'名称',key:'stock_name'},{label:'评分',key:'score'},{label:isTradeable.value?'模拟买入价':'基准收盘',key:'base_close'},{label:isTradeable.value?'模拟卖出价':'次日收盘',key:'actual_close'},{label:'实际收益',key:'actual_return',format:pct},{label:'超额收益',key:'market_excess',format:pct}]);
</script><template><div class="model-tabs"><button v-for="(name,code) in modelNames" :class="{active:activeModel===code}" @click="switchModel(code)">{{name}}</button></div><select v-if="modelRuns.length" v-model="selected[activeModel]" @change="load"><option v-for="r in modelRuns" :value="r.id">信号日 {{r.base_date}} → 验证日 {{r.actual_trade_date}}</option></select><div v-else class="empty compact-empty">该模型尚无正式验证，需要相应未来交易日行情</div><div class="experimental-note"><template v-if="isTradeable">收益按下一交易日开盘模拟买入、再下一交易日开盘模拟卖出计算，尚未扣除费用、滑点及无法成交影响。</template><template v-else>收益按信号日收盘至下一交易日收盘计算，用于验证方向，不代表收盘后下单的可执行收益。</template></div><template v-if="modelRuns.length"><div class="section"><h2>{{modelNames[activeModel]}} TopN验证</h2><DataTable :columns="groups" :rows="data.groups"/></div><div class="section"><h2>{{modelNames[activeModel]}}验证明细</h2><DataTable :columns="detail" :rows="data.detail"/></div></template><StockHistoryModal :stock="historyStock" @close="historyStock=null"/></template>
